public enum AppleError: Swift.Error {



    case NotStarted
    case UnsupportedPlatform
    case AlreadyActive
    case AlreadyStarted
    case PacketQueueFull
    case Network(String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAppleError: FfiConverterRustBuffer {
    typealias SwiftType = AppleError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AppleError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .NotStarted
        case 2: return .UnsupportedPlatform
        case 3: return .AlreadyActive
        case 4: return .AlreadyStarted
        case 5: return .PacketQueueFull
        case 6: return .Network(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AppleError, into buf: inout [UInt8]) {
        switch value {





        case .NotStarted:
            writeInt(&buf, Int32(1))


        case .UnsupportedPlatform:
            writeInt(&buf, Int32(2))


        case .AlreadyActive:
            writeInt(&buf, Int32(3))


        case .AlreadyStarted:
            writeInt(&buf, Int32(4))


        case .PacketQueueFull:
            writeInt(&buf, Int32(5))


        case let .Network(v1):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(v1, into: &buf)

        }
    }
}


