private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 29
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_ray_apple_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_ray_apple_checksum_method_node_activate() != 47813) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_ray_apple_checksum_method_node_create_invite() != 34104) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_ray_apple_checksum_method_node_create_network() != 13138) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_ray_apple_checksum_method_node_deactivate() != 57091) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_ray_apple_checksum_method_node_ipv6_address() != 24181) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_ray_apple_checksum_method_node_join_network() != 54493) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_ray_apple_checksum_method_node_migrate_legacy_state() != 46002) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_ray_apple_checksum_method_node_receive_packets() != 53305) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_ray_apple_checksum_method_node_start() != 7498) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_ray_apple_checksum_method_node_status() != 21690) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_ray_apple_checksum_method_node_stop() != 59801) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_ray_apple_checksum_constructor_node_new() != 28396) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_ray_apple_checksum_method_packetflow_write_packet() != 46369) {
        return InitializationResult.apiChecksumMismatch
    }

    uniffiCallbackInitPacketFlow()
    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsureRayAppleInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

